<script setup lang="ts">
import {computed,ref} from 'vue';import {useRouter} from 'vue-router';import QRCode from 'qrcode';import {useCoffee} from '../stores/coffee';import Modal from '../../../../packages/ui/src/Modal.vue';import {money,createVietQrPayload} from '../../../../packages/shared/src/domain';import type {PaymentIntent} from '../../../../packages/shared/src/types';import Icon from './Icon.vue';
const p=defineProps<{orderId:string}>();const emit=defineEmits(['close']);const s=useCoffee();const router=useRouter();const order=computed(()=>s.state.orders.find(o=>o.id===p.orderId)!);
const method=ref<'cash'|'transfer'>('cash');const received=ref(Math.max(0,order.value.total-order.value.paid));const reference=ref('');const checked=ref(false);const qr=ref('');const intent=ref<PaymentIntent>();const error=ref('');const busy=ref(false);const key=ref(crypto.randomUUID());
const due=computed(()=>Math.max(0,order.value.total-order.value.paid));const change=computed(()=>method.value==='cash'?Math.max(0,received.value-due.value):0);const discount=ref(order.value.discount);const surcharge=ref(order.value.surcharge);
function adjust(){s.run(()=>s.repo.adjust(p.orderId,Number(discount.value),Number(surcharge.value)));received.value=due.value}
async function generate(){error.value='';busy.value=true;const i=s.run(()=>s.repo.createIntent(p.orderId),'');if(i){try{qr.value=await QRCode.toDataURL(createVietQrPayload(i.bank,i.amount,i.reference),{width:320,margin:3,errorCorrectionLevel:'M'});intent.value=i}catch(e){error.value=(e as Error).message}}busy.value=false}
function confirm(){if(!s.canCollect)return;if(method.value==='transfer'&&!checked.value){error.value='Cần kiểm tra giao dịch trước khi xác nhận.';return}const result=s.run(()=>s.repo.collect(p.orderId,method.value,Number(received.value),key.value,reference.value),'');if(result){s.notify('Đã lưu xác nhận trên trình duyệt.'+(result.change?' Tiền trả lại: '+money(result.change):'')+(result.credit?' Tiền thừa cần đối soát: '+money(result.credit):''));key.value=crypto.randomUUID();received.value=due.value;qr.value='';intent.value=undefined;checked.value=false;error.value=''}}
</script>
<template><Modal :title="'Thanh toán · '+order.number" wide @close="emit('close')"><div class="payment-layout"><div><div class="payment-summary"><span>{{order.tableName}}</span><span class="status" :class="due?'pending':'served'">{{due?'Chưa thu đủ':'Đã lưu thu đủ'}}</span></div><div class="receipt-lines"><div v-for="l in order.lines" :key="l.id"><span>{{l.quantity}} × {{l.name}}<small>{{l.variant}} {{l.optionNames.join(', ')}}</small></span><b>{{money(l.total)}}</b></div></div><div class="total-row"><span>Tạm tính</span><b>{{money(order.lines.reduce((n,l)=>n+l.total,0))}}</b></div><div class="adjustments"><label class="field"><span>Giảm giá (đ)</span><input type="number" min="0" v-model.number="discount" :disabled="order.paid>0||Boolean(intent)"></label><label class="field"><span>Phụ thu (đ)</span><input type="number" min="0" v-model.number="surcharge" :disabled="order.paid>0||Boolean(intent)"></label><button class="btn small" @click="adjust" :disabled="order.paid>0||Boolean(intent)">Áp dụng</button></div><div class="total-row"><span>Đã thu</span><b>{{money(order.paid)}}</b></div><div class="total-row grand-total"><strong>Còn phải thu</strong><strong>{{money(due)}}</strong></div><p class="muted small-copy">Xác nhận ở bản xem này chỉ lưu trên trình duyệt; chưa ghi nhận trên máy chủ hoặc kiểm tra ngân hàng.</p><button class="btn outline full" @click="router.push('/receipt/'+order.id);emit('close')"><Icon name="receipt"/>Xem bill & in trình duyệt</button></div><div class="payment-controls"><div class="segmented"><button :class="{selected:method==='cash'}" @click="method='cash'"><Icon name="wallet"/>Tiền mặt</button><button :class="{selected:method==='transfer'}" @click="method='transfer'"><Icon name="bank"/>Chuyển khoản</button></div><template v-if="due"><div v-if="method==='transfer'" class="qr-payment"><template v-if="qr&&intent"><img :src="qr" alt="VietQR yêu cầu chuyển khoản" class="qr-image"><strong>{{money(intent.amount)}}</strong><p>{{intent.bank.bankName}} · {{intent.bank.account}}</p><p>{{intent.bank.holder}}</p><code>{{intent.reference}}</code><a :href="qr" :download="order.number+'-VietQR.png'" class="text-link">Tải mã QR</a></template><template v-else><div class="qr-placeholder"><Icon name="bank" :size="32"/><p>VietQR theo số tiền còn phải thu</p></div><button class="btn outline full" @click="generate" :disabled="busy">{{busy?'Đang tạo mã...':'Tạo VietQR'}}</button><RouterLink v-if="!s.state.banks.some(b=>b.active&&b.branchId===s.branchId)" to="/admin/banks" class="text-link" @click="emit('close')">Thêm tài khoản ngân hàng của cơ sở</RouterLink></template></div><label class="field"><span>{{method==='cash'?'Tiền khách đưa':'Số tiền thực nhận'}} (đ)</span><input type="number" min="1" step="1000" v-model.number="received" aria-label="Số tiền thực nhận"></label><div v-if="change" class="cash-change"><span>Tiền trả lại</span><strong>{{money(change)}}</strong></div><template v-if="method==='transfer'"><label class="field"><span>Mã giao dịch / ghi chú đối soát</span><input v-model="reference" maxlength="80" placeholder="Thông tin giao dịch đã kiểm tra"></label><label class="check-row"><input type="checkbox" v-model="checked"><span>Tôi đã kiểm tra giao dịch nhận tiền</span></label></template><p v-if="error" class="inline-error" role="alert">{{error}}</p><button class="btn primary full" @click="confirm" :disabled="!s.canCollect||!Number.isInteger(received)||received<=0||(method==='transfer'&&!checked)"><Icon name="check"/>Xác nhận thu tiền</button></template><div v-else class="empty"><Icon name="check" :size="40"/><h3>Đã lưu thu đủ tiền</h3><p>In bill hoặc tiếp tục xử lý đơn.</p><button class="btn primary" @click="emit('close')">Hoàn tất</button></div></div></div></Modal></template>
